102 always_ff @(posedge clk or negedge rst_n) begin
103 1/1 if (!rst_n) begin
104 1/1 tid_valid <= 1'b0;
105 1/1 in_i_pipe <= '0;
106 1/1 in_q_pipe <= '0;
107 1/1 bank_enable <= '0;
108 1/1 for (bank = 0; bank < VALID_BANKS; bank = bank + 1) begin
109 1/1 v_i_feedback_local[bank] <= '0;
110 1/1 v_q_feedback_local[bank] <= '0;
111 end
112 1/1 for (p = 0; p < CHANNELS; p = p + 1) begin
113 1/1 v_i[p] <= '0;
114 1/1 v_q[p] <= '0;
115 1/1 for (q = 0; q < CHANNELS; q = q + 1) begin
116 1/1 a_i[p][q] <= '0;
117 1/1 a_q[p][q] <= '0;
118 end
119 end
120 1/1 end else if (tid_ready) begin
121 // The raw boundary holds one word. When it is full and the receiver
122 // stalls, hold both pipeline-valid stages and every recursive state.
123 // Advancing any of them would drop or duplicate a temporal word.
124 // A TID result exists exactly for an accepted input word. Keeping this
125 // asserted through an input bubble duplicates the previous raw-GT word
126 // and corrupts the temporal sequence whenever a real feeder stalls.
127 // Keep the payload flops free-running. The bank-valid pipeline is the
128 // only transaction qualifier, so an invalid or stalled input cannot
129 // alter state but also cannot turn this wide payload bus into a CE tree.
130 1/1 in_i_pipe <= in_i_poly_vec;
131 1/1 in_q_pipe <= in_q_poly_vec;
132 1/1 bank_enable <= {VALID_BANKS{accept_word}};
133 1/1 tid_valid <= bank_enable[0];
134 1/1 for (p = 0; p < CHANNELS; p = p + 1) begin
135 1/1 if (bank_enable[p / BANK_LANES]) begin
136 1/1 for (q = 0; q < CHANNELS; q = q + 1) begin
137 1/1 if (q == 0) begin
138 1/1 a_i[p][q] <= {1'b0, in_i_pipe[p*W +: W] ^ {1'b1, {(W-1){1'b0}}}};
139 1/1 a_q[p][q] <= {1'b0, in_q_pipe[p*W +: W] ^ {1'b1, {(W-1){1'b0}}}};
140 1/1 end else if (p == q) begin
141 1/1 a_i[p][q] <= a_i[p-1][q-1] + a_i[p][q-1];
142 1/1 a_q[p][q] <= a_q[p-1][q-1] + a_q[p][q-1];
143 end else begin
144 1/1 a_i[p][q] <= a_i[p][q-1];
145 1/1 a_q[p][q] <= a_q[p][q-1];
146 end
147 end
148 1/1 v_i[p] <= a_i[p][CHANNELS-1] +
149 {1'b0, v_i_feedback_local[p / BANK_LANES]};
150 1/1 v_q[p] <= a_q[p][CHANNELS-1] +
151 {1'b0, v_q_feedback_local[p / BANK_LANES]};
152 end
MISSING_ELSE
153 end
154 1/1 for (bank = 0; bank < VALID_BANKS; bank = bank + 1) begin
155 1/1 if (bank_enable[bank]) begin
156 1/1 v_i_feedback_local[bank] <= a_i[CHANNELS-1][CHANNELS-1] +
157 {1'b0, v_i_feedback_local[bank]};
158 1/1 v_q_feedback_local[bank] <= a_q[CHANNELS-1][CHANNELS-1] +
159 {1'b0, v_q_feedback_local[bank]};
160 end
MISSING_ELSE
161 end
162 end
MISSING_ELSE
163 end
